import{_ as a,o as e,a as r,b as l}from"./app.DKoEZOcr.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"矩阵计算","link":"/api/SIMD-API/adv_api/cube_compute/cube_compute"},{"text":"Matmul核函数（Kernel）侧接口","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_Kernel"},{"text":"GetNormalConfig","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/GetNormalConfig"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/GetNormalConfig.md","filePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/GetNormalConfig.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787294517000}'),i={name:"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/GetNormalConfig.md"};function s(d,t,n,c,o,b){return e(),r("div",null,[...t[0]||(t[0]=[l(`<div><article class="markdown-body"><h1>GetNormalConfig</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>用于配置Norm模板的参数，获取自定义Norm模板。Norm模板的介绍请参考<a href="MatmulConfig.html#template-features">表模板特性</a>。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>__aicore__ constexpr MatmulConfig GetNormalConfig(const bool intrinsicsLimit = false, const bool batchLoop = false, const bool isVecND2NZ = false, const BatchMode bmmMode = BatchMode::BATCH_LESS_THAN_L1, const bool isMsgReuse = true, const IterateOrder iterateOrder = IterateOrder::UNDEF, const ScheduleType scheduleType = ScheduleType::INNER_PRODUCT, const bool enUnitFlag = true, const bool enableMixDualMaster = false, const BatchOutMode bmmOutMode = BatchOutMode::SINGLE_BATCH)
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p>本接口的所有参数用于设置<a href="MatmulConfig.html#matmulconfig-params">MatmulConfig结构体</a>中的参数，其中互相对应的参数的功能作用相同。</p><p><strong>表1</strong> 接口参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>intrinsicsLimit</td><td>输入</td><td>用于设置参数intrinsicsCheck。<br><br>当左矩阵或右矩阵在单核上内轴（即尾轴）大于等于65535（元素个数）时，是否开启循环执行数据从Global Memory到L1 Buffer的搬入。例如，左矩阵A[M, K]，单核上的内轴数据singleCoreK大于65535，配置该参数为true后，API内部通过循环执行数据的搬入。参数取值如下：<br>false：当左矩阵或右矩阵在单核上内轴大于等于65535时，不开启循环执行数据的搬入（默认值）。<br>true：当左矩阵或右矩阵在单核上内轴大于等于65535时，开启循环执行数据的搬入。<span data-filter="950"><br><br>对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持此参数。</span></td></tr><tr><td>batchLoop</td><td>输入</td><td>用于设置参数isNBatch。<br><br>是否多Batch输入多Batch输出。仅对BatchMatmul有效，开启多Batch后，仅支持Norm模板，且需调用<a href="IterateNBatch.html">IterateNBatch</a>实现多Batch输入多Batch输出。参数取值如下：<br>false：不开启多Batch（默认值）。<br>true：开启多Batch。</td></tr><tr><td>isVecND2NZ</td><td>输入</td><td>用于设置参数enVecND2NZ。<br><br>开启通过vector指令进行ND2NZ。开启时需要设置<a href="SetLocalWorkspace.html">SetLocalWorkspace</a>。参数取值如下：<br>false：不开启通过vector指令进行ND2NZ（默认值）。<br>true：开启通过vector指令进行ND2NZ。<span data-filter="310p"><br><br>针对Atlas 推理系列产品AI Core，在Unified Buffer（UB）空间足够的条件下（UB空间大于2倍TCubeTiling的<a href="../Matmul_Tiling/TCubeTiling_struct.html#p1620315053211">transLength</a>参数），建议优先开启，搬运性能更好。</span><span data-filter="950"><br><br>对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持此参数。</span></td></tr><tr><td>bmmMode</td><td>输入</td><td>用于设置参数batchMode。该参数用于BatchMatmul场景。<br><br>BatchMatmul场景中Layout类型为NORMAL时，设置BatchMatmul输入A/B矩阵的多batch数据总和与L1 Buffer的大小关系。参数取值如下：<br>BatchMode::BATCH_LESS_THAN_L1：多batch数据总和&lt;L1 Buffer Size；<br>BatchMode::BATCH_LARGE_THAN_L1：多batch数据总和&gt;L1 Buffer Size；<br>BatchMode::SINGLE_LARGE_THAN_L1：单batch数据总和&gt;L1 Buffer Size。</td></tr><tr><td>isMsgReuse</td><td>输入</td><td>用于设置参数enableReuse。<br><br><a href="SetSelfDefineData.html">SetSelfDefineData</a>函数设置的回调函数中的dataPtr是否直接传递计算数据。若未调用SetSelfDefineData设置dataPtr，该参数仅支持默认值true。参数取值如下：<br>true：直接传递计算数据，仅限单个值。<br>false：传递GM上存储的数据地址信息。<span data-filter="950"><br><br>对于Ascend 950PR/Ascend 950DT，MxMatmul场景不支持该参数。</span></td></tr><tr><td>iterateOrder</td><td>输入</td><td>用于设置参数iterateOrder。<br><br>Matmul做矩阵运算的循环迭代顺序，与<a href="../Matmul_Tiling/TCubeTiling_struct.html#tcubetiling-struct">表1</a>中的iterateOrder参数含义相同。当ScheduleType参数取值为ScheduleType::OUTER_PRODUCT时，本参数生效。参数取值如下：<br><br>ORDER_M：先往M轴方向偏移再往N轴方向偏移。<br><br>ORDER_N：先往N轴方向偏移再往M轴方向偏移。<br><br>UNDEF：当前无效。<br><br>注：Norm模板的Matmul场景、MDL模板使用时，若IterateOrder取值ORDER_M，<a href="../Matmul_Tiling/TCubeTiling_struct.html#tcubetiling-struct">TCubeTiling结构</a>中的stepN需要大于1，IterateOrder取值ORDER_N时，TCubeTiling结构中的stepM需要大于1。MxMatmul仅支持MDL模板。<span data-filter="A3"><br><br>Atlas A3 训练系列产品/Atlas A3 推理系列产品支持该参数。</span><span data-filter="910b"><br><br>Atlas A2 训练系列产品/Atlas A2 推理系列产品支持该参数。</span><span data-filter="310p"><br><br>Atlas 推理系列产品AI Core不支持该参数。</span><span data-filter="310b"><br><br>Atlas 200I/500 A2 推理产品不支持该参数。</span><span data-filter="x90"><br><br>Kirin X90支持此参数。</span></td></tr><tr><td>scheduleType</td><td>输入</td><td>用于设置参数scheduleType。<br><br>配置Matmul数据搬运模式。参数取值如下：<br>ScheduleType::INNER_PRODUCT：默认模式，在K方向上做MTE1的循环搬运；<br>ScheduleType::OUTER_PRODUCT：在M或N方向上做MTE1的循环搬运；设置该取值后，需要与IterateOrder参数配合使用。该配置当前只在BatchMatmul场景（开启Norm模板）或Matmul场景（开启MDL模板或Norm模板）生效。<br>若IterateOrder取值ORDER_M，则N方向循环搬运（在singleCoreN大于baseN场景可能有性能提升），即B矩阵的MTE1搬运并行；<br>若IterateOrder取值ORDER_N，则M方向循环搬运（在singleCoreM大于baseM场景可能有性能提升），即A矩阵的MTE1搬运并行；<br>不能同时开启M方向和N方向循环搬运；<br><br>注：<br>Norm模板的Batch Matmul场景或者MDL模板中，singleCoreK&gt;baseK时，不能设置为ScheduleType::OUTER_PRODUCT取值，需使用默认模式。<br>Norm模板或MDL模板的Matmul场景，仅支持在纯Cube模式（只有矩阵计算）下配置ScheduleType::OUTER_PRODUCT。<br>MDL模板仅在调用<a href="IterateAll.html">IterateAll</a>计算的场景支持配置ScheduleType::OUTER_PRODUCT。<br>仅在C矩阵输出至GM时，支持配置ScheduleType::OUTER_PRODUCT。<span data-filter="950"><br><br>Ascend 950PR/Ascend 950DT支持该参数。</span><span data-filter="A3"><br><br>Atlas A3 训练系列产品/Atlas A3 推理系列产品支持该参数。</span><span data-filter="910b"><br><br>Atlas A2 训练系列产品/Atlas A2 推理系列产品支持该参数。</span><span data-filter="310p"><br><br>Atlas 推理系列产品AI Core不支持该参数。</span><span data-filter="310b"><br><br>Atlas 200I/500 A2 推理产品不支持该参数。</span><span data-filter="x90"><br><br>Kirin X90支持此参数。</span></td></tr><tr><td>enUnitFlag</td><td>输入</td><td>用于设置参数enUnitFlag。<br><br>开启UnitFlag功能，使计算与搬运流水并行，提高性能。Norm, IBShare下默认开启，MDL下默认不开启。参数取值如下：<br>false：不开启UnitFlag功能。<br>true：开启UnitFlag功能。<span data-filter="950"><br><br>注意：对于Ascend 950PR/Ascend 950DT的MxMatmul场景，仅在NORM/MDL模板、A和scaleA不转置、 B和scaleB转置、C为ND格式，输出到GM场景下，开启UnitFlag功能有性能收益。</span></td></tr><tr><td>enableMixDualMaster</td><td>输入</td><td>用于设置参数enableMixDualMaster。<br><br>是否开启MixDualMaster（双主模式）。区别于MIX模式（包含矩阵计算和矢量计算）通过消息机制驱动AIC运行，双主模式为AIC和AIV独立运行代码，不依赖消息驱动，用于提升性能。该参数默认值为false，仅能在以下场景设置为true：<br>核函数（Kernel）的类型为MIX，同时AIC核数 : AIV核数为1:1。<br>核函数（Kernel）的类型为MIX，同时AIC核数 : AIV核数为1:2，且A矩阵和B矩阵同时开启<a href="Matmul_usage.html#table1188045714378">IBSHARE</a>参数。<br><br>注意，开启MixDualMaster场景，需要满足：<br>同一算子中所有Matmul对象的该参数取值必须保持一致。<br>A/B/Bias矩阵只支持从GM搬入。<br>获取矩阵计算结果只支持调用<a href="IterateAll.html">IterateAll</a>接口输出到GlobalTensor或者LocalTensor，即计算结果放置于Global Memory或者Local Memory的地址，不能调用<a href="GetTensorC.html">GetTensorC</a>等接口获取结果。<span data-filter="950"><br><br>除MxMatmul场景外，Ascend 950PR/Ascend 950DT支持该参数。</span><span data-filter="A3"><br><br>Atlas A3 训练系列产品/Atlas A3 推理系列产品支持该参数。</span><span data-filter="910b"><br><br>Atlas A2 训练系列产品/Atlas A2 推理系列产品支持该参数。</span><span data-filter="310p"><br><br>Atlas 推理系列产品AI Core不支持该参数。</span><span data-filter="310b"><br><br>Atlas 200I/500 A2 推理产品不支持该参数。</span><span data-filter="x90"><br><br>Kirin X90不支持此参数。</span></td></tr><tr><td>bmmOutMode</td><td>输入</td><td>预留参数。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p><a href="MatmulConfig.html#matmulconfig-params">MatmulConfig结构体</a>。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><p>无</p><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 配置Norm模板的参数，获取自定义Norm模板
constexpr MatmulConfig MM_CFG = GetNormalConfig(
    /* intrinsicsLimit   */ false,
    /* batchLoop         */ false,
    /* isVecND2NZ        */ false,
    /* bmmMode           */ BatchMode::BATCH_LESS_THAN_L1,
    /* isMsgReuse        */ true,
    /* iterateOrder      */ IterateOrder::UNDEF,
    /* scheduleType      */ ScheduleType::INNER_PRODUCT,
    /* enUnitFlag        */ true,
    /* enableMixDualMaster */ false,
    /* bmmOutMode        */ BatchOutMode::SINGLE_BATCH);
// 常规Matmul计算，最后输出使用自定义Norm模板的计算结果
AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, MM_CFG&gt; mm;
REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);
mm.SetTensorA(gm_a);
mm.SetTensorB(gm_b);
if (tiling.isBias) {
    mm.SetBias(gmBias);
}
mm.IterateAll(gm_c);
mm.End();
</code></pre></div></article></div>`,1)])])}const p=a(i,[["render",s]]);export{u as __pageData,p as default};
